1|// Track selection and manifest parsing. Pure: no env, no fetch, no audio.
2|import { EMOTIONS } from "./types";
3|import type { EmotionId, Vector8 } from "./types";
4|import { buildFeatures } from "./cluster";
5|
6|// Hand label for the track: the single emotion it was made to carry.
7|export type TrackSource = "generated" | "jamendo" | "recording";
8|
9|export interface Track {
10|  id: string;
11|  src: string;
12|  title: string;
13|  emotion: EmotionId;
14|  vector: Vector8;
15|  intensity: number;
16|  tempo: number;
17|  durationSec: number;
18|  startSec: number;
19|  loop: boolean;
20|  soundtrack: string;
21|  style: string;
22|  source?: TrackSource;
23|  artist?: string;
24|  composer?: string;
25|  license?: string;
26|  attribution?: string;
27|  sourceUrl?: string;
28|}
29|
30|export interface StyleInfo {
31|  id: string;
32|  name: string;
33|}
34|
35|export interface Soundtrack {
36|  id: string;
37|  name: string;
38|  style: string;
39|  credit?: string;
40|}
41|
42|export interface MusicManifest {
43|  version: number;
44|  styles: StyleInfo[];
45|  soundtracks: Soundtrack[];
46|  tracks: Track[];
47|}
48|
49|// Session selection: style scopes every pick, soundtrackId is the home
50|// in soundtrack mode, mode picks the ranking rule.
51|export interface MusicSelection {
52|  mode: "soundtrack" | "random";
53|  soundtrackId: string | null;
54|  style: string | null;
55|}
56|
57|export type Rng = () => number;
58|
59|export interface SelectEnv {
60|  selection: MusicSelection;
61|  rng: Rng;
62|}
63|
64|export interface PersistedMusicPrefs {
65|  mode: "soundtrack" | "random";
66|  soundtrackId: string | null;
67|  style: string | null;
68|}
69|
70|export interface SceneSignal {
71|  vector: Vector8;
72|  intensity: number;
73|  tempo: number;
74|}
75|
76|export type Similarity = (scene: SceneSignal, track: Track, weights: MusicWeights) => number;
77|
78|export interface MusicWeights {
79|  emotion: number;
80|  intensity: number;
81|  tempo: number;
82|}
83|
84|export interface MusicConfig {
85|  similarity: Similarity;
86|  weights: MusicWeights;
87|  switchMargin: number;
88|  dwellSec: number;
89|  minTrackSec: number;
90|  hardCutMargin: number;
91|  crossfadeSec: number;
92|  hardCutCrossfadeSec: number;
93|  randomTolerance: number;
94|}
95|
96|// Renormalize the 8 entries to sum 1. Extra keys (such as a Jev
97|// "unknown" entry) are ignored. An all-zero vector stays all zero.
98|export function normalize8(vector: Record<string, number>): number[] {
99|  const values = EMOTIONS.map((id: EmotionId) => {
100|    const v = vector[id];
101|    return typeof v === "number" && Number.isFinite(v) ? v : 0;
102|  });
103|  const sum = values.reduce((a, b) => a + b, 0);
104|  if (sum <= 0) return values.map(() => 0);
105|  return values.map((v) => v / sum);
106|}
107|
108|// Bhattacharyya affinity over the renormalized shapes, plus separate
109|// intensity and tempo terms. Fair to blended scenes, unlike cosine.
110|export function bhattacharyyaSimilarity(
111|  scene: SceneSignal,
112|  track: Track,
113|  weights: MusicWeights = MUSIC_CONFIG.weights,
114|): number {
115|  const s = normalize8(scene.vector);
116|  const t = normalize8(track.vector);
117|  let affinity = 0;
118|  for (let i = 0; i < s.length; i++) {
119|    affinity += Math.sqrt((s[i] ?? 0) * (t[i] ?? 0));
120|  }
121|  return (
122|    weights.emotion * affinity +
123|    weights.intensity * (1 - Math.abs(scene.intensity - track.intensity)) +
124|    weights.tempo * (1 - Math.abs(scene.tempo - track.tempo))
125|  );
126|}
127|
128|// Cosine over buildFeatures output (vector plus weighted intensity and
129|// tempo). Kept as an alternative; it favors peaky scenes.
130|export function cosineSimilarity(scene: SceneSignal, track: Track): number {
131|  const a = buildFeatures(scene);
132|  const b = buildFeatures(track);
133|  let dot = 0;
134|  let na = 0;
135|  let nb = 0;
136|  for (let i = 0; i < a.length; i++) {
137|    const x = a[i] ?? 0;
138|    const y = b[i] ?? 0;
139|    dot += x * y;
140|    na += x * x;
141|    nb += y * y;
142|  }
143|  if (na === 0 || nb === 0) return 0;
144|  return dot / (Math.sqrt(na) * Math.sqrt(nb));
145|}
146|
147|export const MUSIC_CONFIG: MusicConfig = {
148|  similarity: bhattacharyyaSimilarity,
149|  weights: { emotion: 0.7, intensity: 0.15, tempo: 0.15 },
150|  switchMargin: 0.07,
151|  dwellSec: 20,
152|  minTrackSec: 45,
153|  hardCutMargin: 0.2,
154|  crossfadeSec: 3,
155|  hardCutCrossfadeSec: 1.5,
156|  // Admits near ties into the random-mode draw without letting clearly
157|  // worse matches in.
158|  randomTolerance: 0.05,
159|};
160|
161|export function resolveConfig(override?: Partial<MusicConfig>): MusicConfig {
162|  if (!override) return MUSIC_CONFIG;
163|  return {
164|    ...MUSIC_CONFIG,
165|    ...override,
166|    weights: override.weights ?? MUSIC_CONFIG.weights,
167|  };
168|}
169|
170|export function scoreTrack(
171|  scene: SceneSignal,
172|  track: Track,
173|  override?: Partial<MusicConfig>,
174|): number {
175|  const config = resolveConfig(override);
176|  return config.similarity(scene, track, config.weights);
177|}
178|
179|// Best score first. Ties go to the lower track id, so ranking is stable.
180|export function rankTracks(
181|  scene: SceneSignal,
182|  manifest: MusicManifest,
183|  override?: Partial<MusicConfig>,
184|): Track[] {
185|  const config = resolveConfig(override);
186|  return [...manifest.tracks].sort((a, b) => {
187|    const diff =
188|      config.similarity(scene, b, config.weights) - config.similarity(scene, a, config.weights);
189|    if (diff !== 0) return diff;
190|    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
191|  });
192|}
193|
194|// Dominant emotion of a scene: argmax of the renormalized vector, with
195|// ties broken by EMOTIONS order.
196|export function dominantEmotion(scene: SceneSignal): EmotionId {
197|  const norm = normalize8(scene.vector);
198|  let best: EmotionId = EMOTIONS[0] as EmotionId;
199|  let bestValue = -Infinity;
200|  EMOTIONS.forEach((id: EmotionId, i: number) => {
201|    const value = norm[i] ?? 0;
202|    if (value > bestValue) {
203|      bestValue = value;
204|      best = id;
205|    }
206|  });
207|  return best;
208|}
209|
210|// Reader skip rule: cycle tracks hand-labeled with the scene's dominant
211|// emotion, in score order, wrapping and skipping the current track. When
212|// the current track has another emotion, start at the top candidate. With
213|// no other same-emotion track, fall back to the best track overall that
214|// Style scope for every pick. A null style means the whole manifest,
215|// which only happens before the reader resolves the session style.
216|export function candidatesFor(selection: MusicSelection, manifest: MusicManifest): Track[] {
217|  if (selection.style === null) return manifest.tracks;
218|  return manifest.tracks.filter((t) => t.style === selection.style);
219|}
220|
221|// Home set in soundtrack mode: the session soundtrack, or the whole
222|// style set when none is set yet.
223|export function homeTracks(selection: MusicSelection, styleTracks: Track[]): Track[] {
224|  if (selection.soundtrackId === null) return styleTracks;
225|  const home = styleTracks.filter((t) => t.soundtrack === selection.soundtrackId);
226|  return home.length > 0 ? home : styleTracks;
227|}
228|
229|// "Cambiar track": the next same-emotion track in score order, wrapping
230|// and skipping the current. In soundtrack mode it stays inside the
231|// current track's soundtrack first, then tries the same emotion in other
232|// same-style soundtracks, then the best same-style track overall. In
233|// random mode it ranges over all same-style soundtracks at once. A null
234|// scene cycles the style set in id order. One track or none gives null.
235|export function nextTrack(
236|  scene: SceneSignal | null,
237|  manifest: MusicManifest,
238|  currentTrackId: string | null,
239|  override?: Partial<MusicConfig>,
240|  selection?: MusicSelection | null,
241|): Track | null {
242|  const scope =
243|    selection == null || selection.style === null
244|      ? manifest.tracks
245|      : manifest.tracks.filter((t) => t.style === selection.style);
246|  if (scope.length <= 1) return null;
247|  const config = resolveConfig(override);
248|  const scoped = { ...manifest, tracks: scope };
249|  if (scene === null) {
250|    const ids = [...scope].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
251|    const at = ids.findIndex((t) => t.id === currentTrackId);
252|    return ids[(at + 1) % ids.length] as Track;
253|  }
254|  const ranked = rankTracks(scene, scoped, config);
255|  const same = ranked.filter((t) => t.emotion === dominantEmotion(scene));
256|  const others = same.filter((t) => t.id !== currentTrackId);
257|  if (others.length > 0) {
258|    if (selection?.mode === "random") {
259|      const at = same.findIndex((t) => t.id === currentTrackId);
260|      if (at >= 0) return same[(at + 1) % same.length] as Track;
261|      return same[0] as Track;
262|    }
263|    const current = scope.find((t) => t.id === currentTrackId) ?? null;
264|    const home = current ? same.filter((t) => t.soundtrack === current.soundtrack) : [];
265|    const homeOthers = home.filter((t) => t.id !== currentTrackId);
266|    if (homeOthers.length > 0) {
267|      const at = home.findIndex((t) => t.id === currentTrackId);
268|      if (at >= 0) return home[(at + 1) % home.length] as Track;
269|      return home[0] as Track;
270|    }
271|    const at = same.findIndex((t) => t.id === currentTrackId);
272|    if (at >= 0) return same[(at + 1) % same.length] as Track;
273|    return same[0] as Track;
274|  }
275|  return ranked.find((t) => t.id !== currentTrackId) ?? null;
276|}
277|
278|// Random mode draw: same-style tracks with the scene's dominant emotion
279|// (or the whole style set when none matches), scored, kept within
280|// randomTolerance of the best. The current track stays when eligible;
281|// otherwise the draw skips it when an alternative exists.
282|export function pickRandomTrack(
283|  cands: Track[],
284|  scene: SceneSignal | null,
285|  excludeId: string | null,
286|  rng: Rng,
287|  override?: Partial<MusicConfig>,
288|): Track | null {
289|  if (cands.length === 0) return null;
290|  if (scene === null) {
291|    const ids = [...cands].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
292|    const at = ids.findIndex((t) => t.id === excludeId);
293|    return ids[(at + 1) % ids.length] as Track;
294|  }
295|  const config = resolveConfig(override);
296|  const scoped = { version: 3, styles: [], soundtracks: [], tracks: cands };
297|  const ranked = rankTracks(scene, scoped, config);
298|  const dom = dominantEmotion(scene);
299|  const pool = ranked.filter((t) => t.emotion === dom);
300|  const kept = (pool.length > 0 ? pool : ranked).map((t) => ({
301|    track: t,
302|    score: config.similarity(scene, t, config.weights),
303|  }));
304|  const best = kept[0]?.score ?? 0;
305|  const eligible = kept.filter((e) => e.score >= best - config.randomTolerance);
306|  const current = excludeId !== null ? eligible.find((e) => e.track.id === excludeId) : undefined;
307|  if (current) return current.track;
308|  const rest = eligible.filter((e) => e.track.id !== excludeId);
309|  const drawFrom = rest.length > 0 ? rest : eligible;
310|  if (drawFrom.length === 0) return null;
311|  return (drawFrom[Math.floor(rng() * drawFrom.length)] as { track: Track }).track;
312|}
313|
314|// Distinct hand-labeled emotions on a soundtrack. The initial session
315|// soundtrack is the one covering most emotions, ties by lower id.
316|export function soundtrackCoverage(manifest: MusicManifest, soundtrackId: string): number {
317|  return new Set(
318|    manifest.tracks.filter((t) => t.soundtrack === soundtrackId).map((t) => t.emotion),
319|  ).size;
320|}
321|
322|export function pickInitialSoundtrack(
323|  manifest: MusicManifest,
324|  persistedId: string | null,
325|): string | null {
326|  if (persistedId !== null && manifest.soundtracks.some((s) => s.id === persistedId)) {
327|    return persistedId;
328|  }
329|  let best: string | null = null;
330|  let bestCover = -1;
331|  for (const s of manifest.soundtracks) {
332|    if (!manifest.tracks.some((t) => t.soundtrack === s.id)) continue;
333|    const cover = soundtrackCoverage(manifest, s.id);
334|    if (cover > bestCover || (cover === bestCover && (best === null || s.id < best))) {
335|      best = s.id;
336|      bestCover = cover;
337|    }
338|  }
339|  return best;
340|}
341|
342|function styleHasTracks(manifest: MusicManifest, style: string): boolean {
343|  return manifest.tracks.some((t) => t.style === style);
344|}
345|
346|// Session defaults on load. A stored style with no tracks and a stored
347|// soundtrack outside the stored style both fall back to the defaults.
348|export function resolveInitialSelection(
349|  manifest: MusicManifest,
350|  persisted: PersistedMusicPrefs | null,
351|): MusicSelection {
352|  const fallbackId = pickInitialSoundtrack(manifest, null);
353|  const fallbackStyle =
354|    fallbackId !== null
355|      ? (manifest.soundtracks.find((s) => s.id === fallbackId)?.style ?? null)
356|      : null;
357|  const style =
358|    persisted?.style !== null &&
359|    persisted?.style !== undefined &&
360|    styleHasTracks(manifest, persisted.style)
361|      ? persisted.style
362|      : fallbackStyle;
363|  let soundtrackId: string | null = null;
364|  if (style !== null) {
365|    const inStyle = (id: string) =>
366|      manifest.soundtracks.some((s) => s.id === id && s.style === style);
367|    if (
368|      persisted?.soundtrackId !== null &&
369|      persisted?.soundtrackId !== undefined &&
370|      inStyle(persisted.soundtrackId)
371|    ) {
372|      soundtrackId = persisted.soundtrackId;
373|    } else {
374|      let best: string | null = null;
375|      let bestCover = -1;
376|      for (const s of manifest.soundtracks.filter((s) => s.style === style)) {
377|        if (!manifest.tracks.some((t) => t.soundtrack === s.id)) continue;
378|        const cover = soundtrackCoverage(manifest, s.id);
379|        if (cover > bestCover || (cover === bestCover && (best === null || s.id < best))) {
380|          best = s.id;
381|          bestCover = cover;
382|        }
383|      }
384|      soundtrackId = best;
385|    }
386|  }
387|  return {
388|    mode: persisted?.mode === "random" ? "random" : "soundtrack",
389|    soundtrackId,
390|    style,
391|  };
392|}
393|
394|// Style change from user action: the session soundtrack becomes the best
395|// coverage soundtrack in the new style, and the track is the best match
396|// for the scene within the new style. Never crosses styles. Null when
397|// the style has no tracks.
398|export function requestStyleChange(
399|  manifest: MusicManifest,
400|  style: string,
401|  scene: SceneSignal | null,
402|  override?: Partial<MusicConfig>,
403|): { soundtrackId: string; track: Track } | null {
404|  const scoped = manifest.tracks.filter((t) => t.style === style);
405|  if (scoped.length === 0) return null;
406|  const config = resolveConfig(override);
407|  const inStyle = manifest.soundtracks.filter(
408|    (s) => s.style === style && scoped.some((t) => t.soundtrack === s.id),
409|  );
410|  let soundtrackId = inStyle[0]?.id ?? scoped[0]?.soundtrack ?? "";
411|  let bestCover = -1;
412|  for (const s of inStyle) {
413|    const cover = soundtrackCoverage(manifest, s.id);
414|    if (cover > bestCover || (cover === bestCover && s.id < soundtrackId)) {
415|      soundtrackId = s.id;
416|      bestCover = cover;
417|    }
418|  }
419|  const scopedManifest = { ...manifest, tracks: scoped };
420|  let track: Track;
421|  if (scene === null) {
422|    track = [...scoped].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))[0] as Track;
423|  } else {
424|    track = rankTracks(scene, scopedManifest, config)[0] as Track;
425|  }
426|  return { soundtrackId, track };
427|}
428|
429|const SUPPORTED_VERSION = 3;
430|const SOURCES = ["generated", "jamendo", "recording"] as const;
431|const SLUG = /^[a-z0-9-]+$/;
432|
433|function isRecord(value: unknown): value is Record<string, unknown> {
434|  return typeof value === "object" && value !== null && !Array.isArray(value);
435|}
436|
437|function isOneOf<T extends string>(value: unknown, allowed: readonly T[]): value is T {
438|  return typeof value === "string" && allowed.some((entry) => entry === value);
439|}
440|
441|function isVector8(value: unknown): value is Vector8 {
442|  if (!isRecord(value)) return false;
443|  return EMOTIONS.every(
444|    (id: EmotionId) =>
445|      typeof value[id] === "number" &&
446|      Number.isFinite(value[id]) &&
447|      (value[id] as number) >= 0 &&
448|      (value[id] as number) <= 1,
449|  );
450|}
451|
452|function isUnit(value: unknown): value is number {
453|  return typeof value === "number" && Number.isFinite(value) && value >= 0 && value <= 1;
454|}
455|
456|function isSrc(value: unknown): value is string {
457|  return (
458|    typeof value === "string" && (value.startsWith("/music/") || value.startsWith("https://"))
459|  );
460|}
461|
462|function isNonEmptyString(value: unknown): value is string {
463|  return typeof value === "string" && value !== "";
464|}
465|
466|// Fail loudly on a bad drop-in manifest so broken files never play quiet.
467|export function parseManifest(json: unknown): MusicManifest {
468|  if (!isRecord(json)) throw new Error("manifest must be an object");
469|  if (json.version !== 3 && json.version !== 2) {
470|    throw new Error(`unsupported manifest version: ${String(json.version)}`);
471|  }
472|  // A v2 manifest becomes one implicit soundtrack holding every track.
473|  if (json.version === 2) {
474|    if (!Array.isArray(json.tracks)) throw new Error("manifest tracks must be an array");
475|    const tracks = json.tracks.map((entry, i) => parseTrack(entry, i, "default", "orchestral"));
476|    return {
477|      version: 3,
478|      styles: [{ id: "orchestral", name: "Orquesta" }],
479|      soundtracks: [{ id: "default", name: "Default", style: "orchestral" }],
480|      tracks,
481|    };
482|  }
483|  if (!Array.isArray(json.styles)) throw new Error("manifest styles must be an array");
484|  if (!Array.isArray(json.soundtracks)) throw new Error("manifest soundtracks must be an array");
485|  if (!Array.isArray(json.tracks)) throw new Error("manifest tracks must be an array");
486|  const styles = json.styles.map((entry, i) => {
487|    if (!isRecord(entry)) throw new Error(`style ${i} must be an object`);
488|    if (typeof entry.id !== "string" || !SLUG.test(entry.id)) {
489|      throw new Error(`style ${i} id must be a non-empty lowercase slug`);
490|    }
491|    if (typeof entry.name !== "string" || entry.name === "") {
492|      throw new Error(`style ${entry.id} name must be a non-empty string`);
493|    }
494|    return { id: entry.id, name: entry.name };
495|  });
496|  const styleIds = new Set<string>();
497|  for (const s of styles) {
498|    if (styleIds.has(s.id)) throw new Error(`duplicate style id: ${s.id}`);
