252|    return ids[(at + 1) % ids.length] as Track;
253|  }
254|  const ranked = rankTracks(scene, scoped, config);
255|  const same = ranked.filter((t) => t.emotion === dominantEmotion(scene));
256|  const others = same.filter((t) => t.id !== currentTrackId);
257|  if (others.length > 0) {
258|    if (selection?.mode === "random") {
259|      const at = same.findIndex((t) => t.id === currentTrackId);
