17|export interface SchedulerState {
18|  currentId: string | null;
19|  currentStartedSec: number;
20|  activeSceneId: string | null;
21|  pendingSceneId: string | null;
22|  pendingSinceSec: number;
23|  overrideId: string | null;
24|  overrideSceneId: string | null;
25|}
26|
27|export interface ScheduleDecision {
28|  state: SchedulerState;
29|  switchToId: string | null;
30|  crossfadeSec: number;
31|  hardCut: boolean;
32|  fallback: boolean;
33|}
34|
35|export interface StyleSwitchDecision extends ScheduleDecision {
36|  soundtrackId: string | null;
37|}
