39|export function initScheduler(): SchedulerState {
40|  return {
41|    currentId: null,
42|    currentStartedSec: 0,
43|    activeSceneId: null,
44|    pendingSceneId: null,
45|    pendingSinceSec: 0,
46|    overrideId: null,
47|    overrideSceneId: null,
48|  };
49|}
50|
51|function noChange(state: SchedulerState): ScheduleDecision {
52|  return { state, switchToId: null, crossfadeSec: 0, hardCut: false, fallback: false };
53|}
54|
55|function topRanked(
56|  signal: SceneSignal | null,
57|  manifest: MusicManifest,
58|  config: MusicConfig,
59|  excludeId?: string | null,
60|): { id: string; score: number } | null {
61|  if (signal === null) {
62|    const ids = [...manifest.tracks]
63|      .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
64|      .filter((t) => t.id !== excludeId);
65|    const first = ids[0];
66|    return first ? { id: first.id, score: 0 } : null;
67|  }
68|  const ranked = rankTracks(signal, manifest, config).filter((t) => t.id !== excludeId);
69|  const best = ranked[0];
70|  return best ? { id: best.id, score: scoreTrack(signal, best, config) } : null;
71|}
72|
73|// Pick the switch for a newly active scene: best score wins, but the
74|// current track holds unless the best beats it by switchMargin after
75|// minTrackSec, or by hardCutMargin at once (hard cut, short fade).
76|function gatedEvaluate(
77|  state: SchedulerState,
78|  signal: SceneSignal,
79|  scoped: MusicManifest,
80|  nowSec: number,
81|  config: MusicConfig,
82|): ScheduleDecision {
83|  const best = topRanked(signal, scoped, config);
84|  if (!best) return noChange(state);
85|  const current = scoped.tracks.find((t) => t.id === state.currentId) ?? null;
86|  if (!current || best.id === current.id) {
87|    if (!current) {
88|      return {
89|        state: { ...state, currentId: best.id, currentStartedSec: nowSec },
90|        switchToId: best.id,
91|        crossfadeSec: 0,
92|        hardCut: false,
93|        fallback: false,
94|      };
95|    }
96|    return noChange(state);
97|  }
98|  const gap = best.score - scoreTrack(signal, current, config);
99|  if (gap >= config.hardCutMargin) {
100|    return {
101|      state: { ...state, currentId: best.id, currentStartedSec: nowSec },
102|      switchToId: best.id,
103|      crossfadeSec: config.hardCutCrossfadeSec,
104|      hardCut: true,
105|      fallback: false,
106|    };
107|  }
108|  if (gap >= config.switchMargin && nowSec - state.currentStartedSec >= config.minTrackSec) {
109|    return {
110|      state: { ...state, currentId: best.id, currentStartedSec: nowSec },
111|      switchToId: best.id,
112|      crossfadeSec: config.crossfadeSec,
113|      hardCut: false,
114|      fallback: false,
115|    };
116|  }
117|  return noChange(state);
118|}
