120|// Random mode pick on a scheduled select: the draw keeps the current
121|// track when it is eligible, so rescans do not churn. Dwell is handled
122|// by promotion; min-track holds the current pick.
123|function evaluateRandom(
124|  state: SchedulerState,
125|  signal: SceneSignal,
126|  styleTracks: Track[],
127|  scoped: MusicManifest,
128|  nowSec: number,
129|  config: MusicConfig,
130|  env: SelectEnv,
131|): ScheduleDecision {
132|  const pick = pickRandomTrack(styleTracks, signal, state.currentId, env.rng, config);
133|  if (!pick || pick.id === state.currentId) return noChange(state);
134|  if (state.currentId !== null && nowSec - state.currentStartedSec < config.minTrackSec) {
135|    return noChange(state);
136|  }
137|  return {
138|    state: { ...state, currentId: pick.id, currentStartedSec: nowSec },
139|    switchToId: pick.id,
140|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
141|    hardCut: false,
142|    fallback: false,
143|  };
144|}
145|
146|function evaluateSwitch(
147|  state: SchedulerState,
148|  signal: SceneSignal | null,
149|  manifest: MusicManifest,
150|  nowSec: number,
151|  config: MusicConfig,
152|  env: SelectEnv,
153|): ScheduleDecision {
154|  if (signal === null) return noChange(state);
155|  const styleTracks = candidatesFor(env.selection, manifest);
156|  if (styleTracks.length === 0) return noChange(state);
157|  const scoped = { ...manifest, tracks: styleTracks };
158|  if (env.selection.mode === "random") {
159|    return evaluateRandom(state, signal, styleTracks, scoped, nowSec, config, env);
160|  }
161|  const home = homeTracks(env.selection, styleTracks);
162|  const dom = dominantEmotion(signal);
163|  // Per-scene fallback: when the home soundtrack has no track with the
164|  // scene emotion, borrow the best same-style track for this scene only.
165|  const emo = styleTracks.filter((t) => t.emotion === dom);
166|  const scope = home.some((t) => t.emotion === dom) ? home : emo.length > 0 ? emo : styleTracks;
167|  const decision = gatedEvaluate(state, signal, { ...manifest, tracks: scope }, nowSec, config);
168|  if (decision.switchToId === null) return decision;
169|  const inside = home.some((t) => t.id === decision.switchToId);
170|  // A fallback pick misses the current track in its scope, which reads
171|  // as a first play with no fade. Restore the normal crossfade then.
172|  if (decision.crossfadeSec === 0 && state.currentId !== null) {
173|    return { ...decision, crossfadeSec: config.crossfadeSec, fallback: !inside };
174|  }
175|  return { ...decision, fallback: !inside };
176|}
177|
178|function promote(
179|  state: SchedulerState,
180|  sceneId: string,
181|  signal: SceneSignal | null,
182|  manifest: MusicManifest,
183|  nowSec: number,
184|  config: MusicConfig,
185|  env: SelectEnv,
186|): ScheduleDecision {
187|  const settled: SchedulerState = {
188|    ...state,
189|    activeSceneId: sceneId,
190|    pendingSceneId: null,
191|    pendingSinceSec: 0,
192|    overrideId: null,
193|    overrideSceneId: null,
194|  };
195|  const decision = evaluateSwitch(settled, signal, manifest, nowSec, config, env);
196|  return { ...decision, state: { ...decision.state, activeSceneId: sceneId } };
197|}
198|
199|// The reading position entered a scene. It becomes pending and the dwell
200|// clock restarts, so fast scrolling keeps only the newest scene. After
201|// the pending scene holds for dwellSec it becomes active. The first
202|// track ever plays at once, with no dwell.
203|export function observeScene(
204|  state: SchedulerState,
205|  sceneId: string,
206|  signal: SceneSignal | null,
207|  manifest: MusicManifest,
208|  nowSec: number,
209|  env: SelectEnv,
210|  override?: Partial<MusicConfig>,
211|): ScheduleDecision {
212|  const config = resolveConfig(override ?? MUSIC_CONFIG);
213|  if (state.currentId === null) {
214|    return promote(state, sceneId, signal, manifest, nowSec, config, env);
215|  }
216|  if (sceneId === state.activeSceneId) {
217|    return noChange({ ...state, pendingSceneId: null, pendingSinceSec: 0 });
218|  }
219|  if (sceneId !== state.pendingSceneId) {
220|    return noChange({ ...state, pendingSceneId: sceneId, pendingSinceSec: nowSec });
221|  }
222|  if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
223|  return promote(state, sceneId, signal, manifest, nowSec, config, env);
224|}
225|
226|// Time passed: settle a pending scene whose dwell has expired, or
227|// re-check the active scene (a hold from minTrackSec may have expired).
228|// The reader passes the pending signal when one exists, else the active.
229|export function tickScheduler(
230|  state: SchedulerState,
231|  signal: SceneSignal | null,
232|  manifest: MusicManifest,
233|  nowSec: number,
234|  env: SelectEnv,
235|  override?: Partial<MusicConfig>,
236|): ScheduleDecision {
237|  const config = resolveConfig(override ?? MUSIC_CONFIG);
238|  if (state.currentId === null) return noChange(state);
239|  if (state.pendingSceneId !== null) {
240|    if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
241|    return promote(state, state.pendingSceneId, signal, manifest, nowSec, config, env);
242|  }
243|  // A skip override holds until the next scene change; promotion clears it.
244|  if (state.overrideId !== null) return noChange(state);
245|  if (state.activeSceneId === null) return noChange(state);
246|  return evaluateSwitch(state, signal, manifest, nowSec, config, env);
247|}
248|
249|// Reader skip: the same-emotion Next rule, applied at once with the
250|// normal crossfade. The choice holds until the next scene change.
251|export function requestNext(
252|  state: SchedulerState,
253|  signal: SceneSignal | null,
254|  manifest: MusicManifest,
255|  nowSec: number,
256|  env: SelectEnv,
257|  override?: Partial<MusicConfig>,
258|): ScheduleDecision {
259|  const config = resolveConfig(override ?? MUSIC_CONFIG);
260|  const next = nextTrack(signal, manifest, state.currentId, config, env.selection);
261|  if (!next) return noChange(state);
262|  const home = homeTracks(env.selection, candidatesFor(env.selection, manifest));
263|  return {
264|    state: {
265|      ...state,
266|      currentId: next.id,
267|      currentStartedSec: nowSec,
268|      overrideId: next.id,
269|      overrideSceneId: state.activeSceneId,
270|    },
271|    switchToId: next.id,
272|    crossfadeSec: config.crossfadeSec,
273|    hardCut: false,
274|    fallback: env.selection.mode === "soundtrack" && !home.some((t) => t.id === next.id),
275|  };
276|}
277|
278|// A non-looping track ended: fade into the best remaining track,
279|// excluding the one that just ended. Never crosses styles.
280|export function noteTrackEnded(
281|  state: SchedulerState,
282|  signal: SceneSignal | null,
283|  manifest: MusicManifest,
284|  endedId: string,
285|  nowSec: number,
286|  env: SelectEnv,
287|  override?: Partial<MusicConfig>,
288|): ScheduleDecision {
289|  const config = resolveConfig(override ?? MUSIC_CONFIG);
290|  const styleTracks = candidatesFor(env.selection, manifest).filter((t) => t.id !== endedId);
291|  if (styleTracks.length === 0) return noChange(state);
292|  const best = topRanked(signal, { ...manifest, tracks: styleTracks }, config);
293|  if (!best) return noChange(state);
294|  const home = homeTracks(env.selection, candidatesFor(env.selection, manifest));
295|  return {
296|    state: {
297|      ...state,
298|      currentId: best.id,
299|      currentStartedSec: nowSec,
300|      overrideId: null,
301|      overrideSceneId: null,
302|    },
303|    switchToId: best.id,
304|    crossfadeSec: config.crossfadeSec,
305|    hardCut: false,
306|    fallback: env.selection.mode === "soundtrack" && !home.some((t) => t.id === best.id),
307|  };
308|}
309|
310|// Style change from user action: switches at once with the normal
311|// crossfade, no dwell and no min-track rule, and sets the override like
312|// Next. Returns the new session soundtrack so the reader can store it.
313|export function switchStyle(
314|  state: SchedulerState,
315|  signal: SceneSignal | null,
316|  manifest: MusicManifest,
317|  nowSec: number,
318|  style: string,
319|  override?: Partial<MusicConfig>,
320|): StyleSwitchDecision {
321|  const config = resolveConfig(override ?? MUSIC_CONFIG);
322|  const picked = requestStyleChange(manifest, style, signal, config);
323|  if (!picked) return { ...noChange(state), soundtrackId: null };
