328|    state: {
329|      ...state,
330|      currentId: picked.track.id,
331|      currentStartedSec: nowSec,
332|      overrideId: picked.track.id,
333|      overrideSceneId: state.activeSceneId,
334|    },
335|    switchToId: picked.track.id,
