590|    let loops = true;
591|    if (loop !== undefined) {
592|      if (typeof loop !== "boolean") throw new Error(`track ${id} loop must be a boolean`);
593|      loops = loop;
594|    }
595|    let trackSource: TrackSource | undefined;
596|    if (source !== undefined) {
597|      if (!isOneOf(source, SOURCES)) {
598|        throw new Error(`track ${id} source must be generated, jamendo, or recording`);
599|      }
600|      trackSource = source;
601|    }
602|    const credit: { artist?: string; composer?: string; license?: string; attribution?: string } = {};
603|    const pairs = [
604|      ["artist", artist],
605|      ["composer", composer],
606|      ["license", license],
607|      ["attribution", attribution],
608|    ] as const;
609|    for (const [key, value] of pairs) {
610|      if (value === undefined) continue;
611|      if (!isNonEmptyString(value)) throw new Error(`track ${id} ${key} must be a non-empty string`);
612|      credit[key] = value;
613|    }
614|    if (sourceUrl !== undefined && (typeof sourceUrl !== "string" || !sourceUrl.startsWith("https://"))) {
615|      throw new Error(`track ${id} sourceUrl must be an https URL`);
616|    }
617|    return {
618|      id,
619|      src,
620|      title,
621|      emotion,
622|      vector,
623|      intensity,
624|      tempo,
625|      durationSec,
626|      startSec: start,
627|      loop: loops,
628|      soundtrack,
629|      style,
630|      ...credit,
631|      ...(trackSource === undefined ? {} : { source: trackSource }),
