5|import type { MusicManifest, MusicSelection, SceneSignal, Track } from "@/core/music";
6|import {
7|  initScheduler,
8|  noteTrackEnded,
9|  observeScene,
10|  requestNext,
11|  switchStyle,
12|  tickScheduler,
13|} from "@/core/music-schedule";
14|import type { SchedulerState } from "@/core/music-schedule";
15|import { pickActiveScene } from "./active-scene";
16|import { loadMusicPrefs, saveMusicPrefs } from "./music-prefs";
17|import { Player } from "./player";
18|
19|export interface SceneMeta {
20|  id: string;
21|  title: string;
22|  emotion: SceneSignal | null;
23|}
24|
25|// Client container: tracks the active scene, runs the pure scheduler
26|// with wall-clock seconds, and passes the chosen track to the player.
27|export function Reader({ scenes, children }: { scenes: SceneMeta[]; children: React.ReactNode }) {
28|  const [activeId, setActiveId] = useState<string | null>(scenes[0]?.id ?? null);
29|  const [manifest, setManifest] = useState<MusicManifest | null>(null);
30|  const [selection, setSelection] = useState<MusicSelection | null>(null);
31|  const [musicFailed, setMusicFailed] = useState(false);
32|  const [currentId, setCurrentId] = useState<string | null>(null);
33|  const [fadeSec, setFadeSec] = useState(0);
34|  const [isFallback, setIsFallback] = useState(false);
35|  const byId = useMemo(() => new Map(scenes.map((s) => [s.id, s])), [scenes]);
36|  const schedRef = useRef<SchedulerState>(initScheduler());
37|  const liveRef = useRef({ activeId, manifest, selection, currentId, byId });
38|  liveRef.current = { activeId, manifest, selection, currentId, byId };
39|
40|  const nowSec = () => Date.now() / 1000;
41|
42|  const applyDecision = useCallback((decision: {
43|    state: SchedulerState;
44|    switchToId: string | null;
45|    crossfadeSec: number;
46|    fallback: boolean;
47|  }) => {
48|    schedRef.current = decision.state;
49|    setActiveId(decision.state.activeSceneId);
50|    setIsFallback(decision.fallback);
51|    if (decision.switchToId !== null) {
52|      setCurrentId(decision.switchToId);
53|      setFadeSec(decision.crossfadeSec);
54|    }
55|  }, []);
56|
57|  const persist = useCallback((next: MusicSelection) => {
58|    setSelection(next);
59|    saveMusicPrefs({
60|      mode: next.mode,
61|      soundtrackId: next.soundtrackId,
62|      style: next.style,
63|    });
64|  }, []);
65|
66|  const observe = useCallback(
67|    (sceneId: string) => {
68|      const st = liveRef.current;
69|      if (!st.manifest || !st.selection) return;
70|      const signal = st.byId.get(sceneId)?.emotion ?? null;
71|      applyDecision(
72|        observeScene(schedRef.current, sceneId, signal, st.manifest, nowSec(), {
73|          selection: st.selection,
74|          rng: Math.random,
75|        }),
76|      );
77|    },
78|    [applyDecision],
79|  );
