81|  useEffect(() => {
82|    let cancelled = false;
83|    fetch("/music/manifest.json")
84|      .then((res) => {
85|        if (!res.ok) throw new Error(`manifest ${res.status}`);
86|        return res.json();
87|      })
88|      .then((json: unknown) => {
89|        if (cancelled) return;
