98|      cancelled = true;
99|    };
100|  }, []);
101|
102|  // Reselect once the manifest lands so the first scene gets music.
103|  useEffect(() => {
104|    if (!manifest) return;
105|    const st = liveRef.current;
106|    if (st.activeId) observe(st.activeId);
107|  }, [manifest, observe]);
108|
109|  useEffect(() => {
110|    const snapshot = () =>
111|      [...document.querySelectorAll<HTMLElement>("section[data-scene-id]")].map((el) => ({
112|        id: el.dataset.sceneId ?? "",
113|        top: el.getBoundingClientRect().top,
114|      }));
115|    const readActive = () => pickActiveScene(snapshot(), window.innerHeight / 3);
116|    const observer = new IntersectionObserver(
117|      () => {
118|        // Entries are only a trigger; every callback re-snapshots live rects.
119|        const next = readActive();
120|        if (next) observe(next);
121|      },
122|      { rootMargin: "-30% 0px -65% 0px" },
123|    );
124|    document.querySelectorAll("section[data-scene-id]").forEach((el) => observer.observe(el));
125|    const first = readActive();
126|    if (first) observe(first);
127|    const timer = window.setInterval(() => {
128|      // Settle an expired dwell, or re-check the active scene after a hold.
129|      const st = liveRef.current;
130|      if (!st.manifest || !st.selection || !st.activeId) return;
131|      const sceneId = schedRef.current.pendingSceneId ?? st.activeId;
132|      const signal = st.byId.get(sceneId)?.emotion ?? null;
133|      applyDecision(
134|        tickScheduler(schedRef.current, signal, st.manifest, nowSec(), {
135|          selection: st.selection,
136|          rng: Math.random,
137|        }),
138|      );
139|    }, 1000);
140|    return () => {
141|      observer.disconnect();
142|      window.clearInterval(timer);
143|    };
144|  }, [observe, applyDecision]);
145|
146|  function skip() {
147|    const st = liveRef.current;
148|    if (!st.manifest || !st.selection || !st.activeId) return;
149|    const signal = st.byId.get(st.activeId)?.emotion ?? null;
150|    applyDecision(
151|      requestNext(schedRef.current, signal, st.manifest, nowSec(), {
152|        selection: st.selection,
153|        rng: Math.random,
154|      }),
155|    );
156|  }
157|
158|  function toggleMix() {
159|    const st = liveRef.current;
160|    if (!st.manifest || !st.selection) return;
161|    if (st.selection.mode === "random") {
162|      // Mixing off keeps the soundtrack of the playing track.
163|      const playing = st.manifest.tracks.find((t) => t.id === st.currentId) ?? null;
164|      persist({
165|        mode: "soundtrack",
166|        soundtrackId: playing?.soundtrack ?? st.selection.soundtrackId,
167|        style: playing?.style ?? st.selection.style,
168|      });
169|      return;
170|    }
171|    persist({ ...st.selection, mode: "random" });
172|  }
173|
174|  function changeStyle(style: string) {
175|    const st = liveRef.current;
176|    if (!st.manifest || !st.selection || !st.activeId || style === st.selection.style) return;
177|    const signal = st.byId.get(st.activeId)?.emotion ?? null;
178|    const decision = switchStyle(schedRef.current, signal, st.manifest, nowSec(), style);
179|    if (decision.soundtrackId === null) return;
