189|      noteTrackEnded(schedRef.current, signal, st.manifest, trackId, nowSec(), {
190|        selection: st.selection,
191|        rng: Math.random,
192|      }),
193|    );
194|  }
195|
196|  const track: Track | null = manifest?.tracks.find((t) => t.id === currentId) ?? null;
197|  const sceneTitle = (activeId && byId.get(activeId)?.title) || null;
198|  const empty = manifest !== null && manifest.tracks.length === 0;
199|  const activeSignal = (activeId && byId.get(activeId)?.emotion) || null;
200|  const soundtrackName =
201|    manifest?.soundtracks.find((s) => s.id === track?.soundtrack)?.name ?? null;
