206|    manifest !== null &&
207|    selection !== null &&
208|    manifest.tracks.length > 1 &&
209|    nextTrack(activeSignal ?? null, manifest, currentId, undefined, selection) !== null;
210|
211|  return (
212|    <>
213|      <div className="player-bar">
214|        {musicFailed || empty ? (
215|          <p className="player-note">Music unavailable. The reader works without it.</p>
216|        ) : (
217|          <Player
218|            track={track}
219|            fadeSec={fadeSec}
220|            sceneTitle={sceneTitle}
221|            soundtrackName={soundtrackName}
222|            isFallback={isFallback}
